class WeatherSystem {

    /*
    This is a class representing a weather system that provides functionality to query weather information for a specific city and convert temperature units between Celsius and Fahrenheit.
    */

    var temperature: Float64
    var weather: String
    var city: String
    var weather_list: HashMap<String, Weather>

    public init(city: String) {
        /*
        Initialize the weather system with a city name.
        */
        this.temperature = Float64.NaN
        this.weather = ""
        this.city = city
        this.weather_list = HashMap<String, Weather>()
    }

    public func query(weather_list: HashMap<String, Weather>, tmp_units!: String = 'celsius'): Option<(Float64, String)> {
        /*
        Query the weather system for the weather and temperature of the city,and convert the temperature units based on the input parameter.
        :param weather_list: a dictionary of weather information for different cities,HashMap<String, Weather>.
        :param tmp_units: the temperature units to convert to, String.
        :return: the temperature and weather of the city, Option<Float64, String>.
        >>> weatherSystem = WeatherSystem('New York')
        >>> weather_list = HashMap<String, Weather>()
        >>> weather_list['New York'] = Weather('sunny', 27.0, 'celsius')
        >>> weather_list['Beijing'] = Weather('cloudy', 23.0, 'celsius')
        >>> weatherSystem.query(weather_list)
        (27.0, 'sunny')

        */
        let opt_weather: Option<Weather> = weather_list.get(this.city)
        if (opt_weather != None) {
            let current_weather: Weather = opt_weather.getOrThrow()
            this.weather = current_weather.weather
            this.temperature = current_weather.temperature

            if (tmp_units == 'fahrenheit') {
                let fahrenheit: Float64 = this.celsius_to_fahrenheit()
                return Some((fahrenheit, this.weather))
            } else {
                return Some((this.temperature, this.weather))
            }
        } else {
            return None
        }
    }

    public func set_city(city: String): Unit {
        /*
        Set the city of the weather system.
        :param city: the city to set, String.
        :return: Unit
        >>> weatherSystem = WeatherSystem('New York')
        >>> weatherSystem.set_city('Beijing')
        >>> weatherSystem.city
        'Beijing'

        */
        this.city = city
    }

    public func celsius_to_fahrenheit(): Float64 {
        /*
        Convert the temperature from Celsius to Fahrenheit.
        :return: the temperature in Fahrenheit, Float64.
        >>> weatherSystem = WeatherSystem('New York')
        >>> weatherSystem.temperature = 27.0
        >>> weatherSystem.celsius_to_fahrenheit()
        80.6

        */
        return (this.temperature * 9.0 / 5.0) + 32.0
    }

    public func fahrenheit_to_celsius(): Float64 {
        /*
        Convert the temperature from Fahrenheit to Celsius.
        :return: the temperature in Celsius, Float64.
        >>> weatherSystem = WeatherSystem('New York')
        >>> weatherSystem.temperature = 80.6
        >>> weatherSystem.fahrenheit_to_celsius()
        26.999999999999996

        */
        return (this.temperature - 32.0) * 5.0 / 9.0
    }
}

import std.collection.HashMap
import std.collection.ArrayList

class Words2Numbers {

    /*
    The class provides a text-to-number conversion utility, allowing conversion of written numbers (in words) to their numerical representation.
    */

    let numwords: HashMap<String, (Int64, Int64)>
    let units: ArrayList<String>
    let tens: ArrayList<String>
    let scales: ArrayList<String>
    let ordinal_words: HashMap<String, Int64>
    let ordinal_endings: ArrayList<(String, String)>

    public init() {
        /*
        Initialize the word lists and dictionaries required for conversion
        */
        this.numwords = HashMap<String, (Int64, Int64)>()
        this.units = ArrayList<String>(["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"])
        this.tens = ArrayList<String>(["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"])
        this.scales = ArrayList<String>(["hundred", "thousand", "million", "billion", "trillion"])

        this.numwords["and"] = (1, 0)
        for (idx in 0..this.units.size) {
            if (idx < this.units.size) {
                this.numwords[this.units[idx]] = (1, idx)
            }
        }
        for (idx in 0..this.tens.size) {
            if (idx < this.tens.size) {
                this.numwords[this.tens[idx]] = (1, idx * 10)
            }
        }
        for (idx in 0..this.scales.size) {
            if (idx < this.scales.size) {
                if (idx == 0) { // hundred
                    this.numwords[this.scales[idx]] = (100, 0)
                } else {
                    // For thousand, million, billion, trillion: 10^(3*idx)
                    this.numwords[this.scales[idx]] = (Int64(10 ** (3 * idx)), 0)
                }
            }
        }

        this.ordinal_words = HashMap<String, Int64>([("first", 1), ("second", 2), ("third", 3), ("fifth", 5), ("eighth", 8), ("ninth", 9), ("twelfth", 12)])
        this.ordinal_endings = ArrayList<(String, String)>([("ieth", "y"), ("th", "")])
    }

    public func text2int(textnum: String): String {
        /*
        Convert the word string to the corresponding integer string
        :param textnum: String, the word string to be converted
        :return: String, the final converted integer string
        >>> w2n = Words2Numbers()
        >>> w2n.text2int("thirty-two")
        "32"
        */
        var text = textnum.lowercase()

        // Replace hyphens with spaces
        text = text.replace("-", " ")

        // Split the text into words
        let words = text.split(" ")

        var current = Int64(0)
        var total = Int64(0)
        var prev_scale = Int64(1)

        for word in words {
            if (word == "") {
                continue
            }

            var processed_word = word

            // Handle ordinal numbers
            for (ending, replacement) in this.ordinal_endings {
                if (word.endsWith(ending)) {
                    processed_word = word.substring(0, word.size - ending.size) + replacement
                    break
                }
            }

            // Check if this is an ordinal word
            if (this.ordinal_words.containsKey(processed_word)) {
                return this.ordinal_words[processed_word].toString()
            }

            // Check if the word is in our dictionary
            if (!this.numwords.containsKey(processed_word)) {
                throw "Invalid word: ${processed_word}"
            }

            let (scale, increment) = this.numwords[processed_word]

            if (scale > 1) {
                // This is a scale word (hundred, thousand, million, etc.)
                if (scale > prev_scale) {
                    total += current * scale
                    current = 0
                } else {
                    current *= scale
                }
                prev_scale = scale
            } else if (increment > 0 || processed_word == "zero") {
                // This is a unit or tens word
                current += increment
            }
            // "and" is handled as (1, 0) which doesn't affect the values
        }

        total += current
        return total.toString()
    }

    public func is_valid_input(textnum: String): Bool {
        /*
        Check if the input text contains only valid words that can be converted into numbers.
        :param textnum: The input text containing words representing numbers.
        :return: true if input is valid, false otherwise.
        >>> w2n = Words2Numbers()
        >>> w2n.is_valid_input("thirty-two")
        false
        */
        var text = textnum.lowercase()
        text = text.replace("-", " ")
        let words = text.split(" ")

        for word in words {
            if (word == "") {
                continue
            }

            var processed_word = word

            // Handle ordinal endings
            for (ending, replacement) in this.ordinal_endings {
                if (word.endsWith(ending)) {
                    processed_word = word.substring(0, word.size - ending.size) + replacement
                    break
                }
            }

            // Check if this is an ordinal word
            if (this.ordinal_words.containsKey(processed_word)) {
                continue
            }

            // Check if the word is in our dictionary
            if (!this.numwords.containsKey(processed_word)) {
                return false
            }
        }

        return true
    }
}
